import{_ as e,o as t,c as p,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/BINOMIAL.md","filePath":"manual-zh/BINOMIAL.md","lastUpdated":1785684581000}'),o={name:"manual-zh/BINOMIAL.md"};function _(n,a,s,d,l,c){return t(),p("div",null,[...a[0]||(a[0]=[r(`<h4 id="_15-12-1-二项检验" tabindex="-1">15.12.1 二项检验 <a class="header-anchor" href="#_15-12-1-二项检验" aria-label="Permalink to &quot;15.12.1 二项检验&quot;">​</a></h4><pre><code>     [ /BINOMIAL[(p)]=var_list[(value1[, value2)] ] ]
</code></pre><p><code>/BINOMIAL</code> 子命令将二分变量的观测分布与二项分布进行比较。变量 p 指定了二项分布的检验比例。若省略 p，则默认取 0.5。</p><p>如果变量列表后只出现一个值，则该值用作划分观测值的阈值。小于或等于该阈值的值构成第一类。大于该阈值的值构成第二类。</p><p>如果变量列表后出现两个值，则它们作为变量必须取的值，以归入各自的类别。变量取值既不等于这两个指定值中任何一个的个案，不参与该变量的检验。</p><p>如果未出现任何值，则变量必须为二分取值。若遇到被检验变量存在两个以上不同的非缺失值，则会发生错误。</p><p>如果检验比例为 0.5，则报告双尾检验。对于其他任何检验比例，报告单尾检验。对于单尾检验，如果检验比例小于或等于观测比例，则报告观测到该比例或更大的显著性；如果检验比例大于观测比例，则报告观测到该比例或更小的显著性。也就是说，检验总是按观测的方向进行。</p><p>PSPP 使用对 gamma 函数的高精度近似来计算二项检验的显著性。因此，即使样本量非常大，也会报告精确结果。</p>`,8)])])}const I=e(o,[["render",_]]);export{m as __pageData,I as default};
